-- Historical typed defaults, never regenerated by the release check.
local root, flavor = assert(arg[1]), assert(arg[2])
local S = assert(loadfile(root .. '/tools/fixtures/defaults/schema.lua'))()
local C = assert(loadfile(root .. '/tools/profile_corpus_golden.lua'))()
local H = assert(loadfile(root .. '/tools/tests/profile_state_harness.lua'))()
local w = C.NewWorld(root, flavor, 'Defaults-Realm', function(world)
    world.env.GetNumSubgroupMembers = function() return 0 end
end)
C.Login(w, {})
local ns, P = w.core, w.core.PublicGlobals
local function Expected(row, id, mode) return S.clients[flavor][mode][id] or row[mode] end
local function Get(owner, path)
    for _, key in ipairs(path) do
        if type(owner) ~= 'table' then return nil end
        owner = owner[key]
    end
    return owner
end
local function Check(profile, mode)
    for id, row in ipairs(S.fields) do
        local value, expected = Get(profile, row.path), Expected(row, id, mode)
        assert(type(value) == expected[1] and (expected[1] == 'table' or value == expected[2]),
            flavor .. '/' .. mode .. ': ' .. table.concat(row.path, '.') .. ': expected '
            .. expected[1] .. '/' .. tostring(expected[2]) .. ', got ' .. type(value) .. '/' .. tostring(value))
    end
end
local function Stages()
    local stages = {}
    for id, row in pairs(S.stages) do
        stages[id] = {}
        for key, value in pairs(row.fields) do stages[id][key] = value[2] end
    end
    assert(H.Literal(stages) == H.Literal(ns.DefaultsSchema.SeedStages), 'historical repair seed stages differ')
end
local function Complete(profile)
    w.env.MSUF_DB = profile
    P.MSUF_NormalizeProfileDefaults(profile, true)
    ns.ProfileIOEnsureCompleteProfileDB()
    -- Exercise the real cold lazy-default providers, before any frame failure.
    local builder = P.MSUF_CP_CONST.BuilderRegistry('MSUF_CP_CORE_BUILDERS').CONTROLLER_CONFIG
    local found = false
    for i = 1, 60 do
        local name, value = debug.getupvalue(builder, i)
        if not name then break end
        if name == 'EnsureDefaults' then value(); found = true end
    end
    assert(found, 'class power lazy-default provider disappeared')
    ns.MSUF_EnsureGameplayDefaults()
    ns.ProfileNormalize.EnsureProfileMenuDefaults(profile)
    local a3 = ns.MSUF_Auras3
    if a3 and a3.Runtime and a3.Runtime.CustomConfig then
        local item = profile.auras3.customContainers.perUnit.player.items[4]
        a3.Runtime.CustomConfig.ResolveSpecialCustomStyle(profile.auras3, 'player', 4, item)
    end
    return profile
end
local function Repair()
    local profile = { _schemaOracleRepair = true }
    -- These are historical mock frame-placement inputs, not scalar default
    -- declarations: their migration depends on the already-built native frame
    -- geometry. The corpus independently pins the complete login geometries.
    for id, row in ipairs(S.fields) do
        local owner, key = row.path[1], row.path[2]
        if #row.path == 2 and owner:match('^gf_') and (key == 'offsetX' or key == 'offsetY'
            or key:match('^position') or key == '_resolvedFrameScale') then
            profile[owner] = profile[owner] or {}
            profile[owner][key] = Expected(row, id, 'repair')[2]
        end
    end
    return Complete(profile)
end
Stages()
Check(Complete(assert(P.MSUF_CreateFactoryDefaultProfile())), 'factory')
Check(Repair(), 'repair')
-- An intentional provider mutation must fail against the historical fixture.
local stage = ns.DefaultsSchema.SeedStages.bars_04
local old = stage.gcdBarHeight
stage.gcdBarHeight = old + 1
assert(not pcall(Stages), 'changed repair declaration passed the historical oracle')
assert(not pcall(function() Check(Repair(), 'repair') end), 'changed repair default passed the historical oracle')
stage.gcdBarHeight = old
local factory = Complete(assert(P.MSUF_CreateFactoryDefaultProfile()))
factory.player.width = factory.player.width + 1
assert(not pcall(function() Check(factory, 'factory') end), 'changed factory default passed the historical oracle')
print(('defaults oracle: %s, %d factory + %d repair paths; seed parity and negative mutations passed'):format(
    flavor, #S.fields, #S.fields))
